WorldControl::WorldControl(juce::AudioProcessorValueTreeState&s,int pad,world::Param p):parameter(p){auto&spec=world::specs[(size_t)p];addAndMakeVisible(label);label.setText(spec.name,juce::dontSendNotification);label.setJustificationType(juce::Justification::centred);label.setFont(juce::Font(12.f,juce::Font::bold));if(spec.choices[0]){addAndMakeVisible(combo);combo.addItemList(juce::StringArray::fromTokens(spec.choices,"|",""),1);}else{addAndMakeVisible(knob);knob.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);knob.setTextBoxStyle(juce::Slider::TextBoxBelow,false,76,20);knob.setDoubleClickReturnValue(true,spec.initial);knob.setName(spec.name);}bind(s,pad);}
void WorldControl::bind(juce::AudioProcessorValueTreeState&s,int pad){sa.reset();ca.reset();auto key=WorldProcessor::id(pad,parameter);if(world::specs[(size_t)parameter].choices[0])ca=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(s,key,combo);else sa=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(s,key,knob);}
void WorldControl::resized(){auto r=getLocalBounds();label.setBounds(r.removeFromTop(21));if(world::specs[(size_t)parameter].choices[0])combo.setBounds(r.reduced(4,juce::jmax(1,(r.getHeight()-29)/2)));else knob.setBounds(r.reduced(4));}
void WorldPad::paint(juce::Graphics&g){bool selected=processor.selectedPad.load()==index;float peak=processor.padPeaks[(size_t)index].load();bool hit=isMouseButtonDown();auto r=getLocalBounds().toFloat().reduced(4.f);g.setColour(juce::Colours::black.withAlpha(.8f));g.fillRoundedRectangle(r.translated(1.f,4.f),9);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff080b0d),r.getTopLeft(),juce::Colour(0xff646768),r.getBottomRight(),false));g.fillRoundedRectangle(r,9);auto face=r.reduced(3.f).translated(0,hit?2.f:-1.f);auto base=selected?juce::Colour(0xff765d33):juce::Colour(0xff3c4348);g.setGradientFill(juce::ColourGradient(base.brighter(.17f),face.getTopLeft(),base.darker(.5f),face.getBottomRight(),false));g.fillRoundedRectangle(face,7);g.setColour(selected?accent:juce::Colour(0xff7b8287));g.drawRoundedRectangle(face,7,selected?2.f:1.f);g.setColour(juce::Colours::white.withAlpha(.18f));g.drawLine(face.getX()+8,face.getY()+2,face.getRight()-8,face.getY()+2,1);g.setColour(cream);g.setFont(juce::Font(17.f,juce::Font::bold));g.drawText("PAD "+juce::String(index+1),6,8,getWidth()-12,23,juce::Justification::centred);bool isSample=processor.state.getRawParameterValue(WorldProcessor::id(index,world::Source))->load()>.5f;juce::String name=isSample?processor.sampleName(index):processor.padTitle(index);g.setFont(11.f);g.drawFittedText(name,9,35,getWidth()-18,getHeight()-55,juce::Justification::centred,2);auto led=r.withY(r.getBottom()-12).withHeight(5).reduced(10.f,0.f);if(peak>.001f){g.setColour(accent.withAlpha(.18f));g.fillRoundedRectangle(led.expanded(3),4);}g.setColour(peak>.001f?juce::Colour(0xffffd45c):juce::Colour(0xff101518));g.fillRoundedRectangle(led,2);}
void WorldPad::mouseDown(const juce::MouseEvent&){if(onSelect)onSelect(index);else processor.selectPad(index);processor.triggers[(size_t)index].fetch_add(1);repaint();}
void WorldWaveform::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff151c20));auto sample=processor.sampleData(processor.selectedPad.load());g.setColour(cream);g.setFont(12.f);if(!sample){juce::String prompt=processor.recordStatus.load()==1?"RECORDING "+juce::String(processor.recordingSeconds(),1)+" seconds — play your pads, then STOP REC":(processor.recordStatus.load()==2?"Recording ready — USE / PLAY REC to load and audition it, or SAVE REC WAV to export":"LOAD SAMPLE imports WAV / AIFF / FLAC / OGG onto this pad. REC captures the full VOG mix by default.");g.drawText(prompt,getLocalBounds().reduced(14),juce::Justification::centredLeft);return;}int frames=(int)sample->left.size();if(frames<2)return;g.setColour(accent);float mid=getHeight()*.5f;for(int x=0;x<getWidth();x++){int first=(int)((int64_t)x*frames/getWidth()),last=std::min(frames,(int)((int64_t)(x+1)*frames/getWidth())+1);float low=1,high=-1;int stride=std::max(1,(last-first)/32);for(int i=first;i<last;i+=stride){float value=juce::jlimit(-1.f,1.f,(sample->left[(size_t)i]+sample->right[(size_t)i])*.5f);low=std::min(low,value);high=std::max(high,value);}g.drawVerticalLine(x,mid-high*mid*.85f,mid-low*mid*.85f);}}
