WorldEditor::~WorldEditor(){stopTimer();setLookAndFeel(nullptr);}
void WorldEditor::result(const juce::Result&r){notice=r.wasOk()?"Done":r.getErrorMessage();noticeTicks=150;}
void WorldEditor::openSaveWav(bool recording){const juce::Component::SafePointer<WorldEditor>guard(this);int pad=processor.selectedPad.load();if(recording&&processor.recordStatus.load()!=2){result(juce::Result::fail("Stop a recording first"));return;}chooser=std::make_unique<juce::FileChooser>(recording?"Save recording WAV":"Save selected pad sample WAV",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile(recording?"World Recording.wav":"World Pad.wav"),"*.wav");chooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[guard,recording,pad](const juce::FileChooser&f){if(guard&&f.getResult()!=juce::File())guard->result(guard->processor.saveWav(f.getResult().withFileExtension("wav"),recording,pad));});}
void WorldEditor::select(int pad){selected=pad;processor.selectPad(pad);for(auto&c:controls)c->bind(processor.state,pad);program=-1;rebuildPatches();}
void WorldEditor::rebuildPatches(bool chooseFirst){int current=processor.getCurrentProgram();patches.clear(juce::dontSendNotification);visiblePatches.clear();int filter=family.getSelectedId()-2;for(int i=0;i<(int)world::patches.size();i++){auto&p=world::patches[(size_t)i];if((region<0||p.region==region)&&(filter<0||p.family==filter)){patches.addItem(juce::String::fromUTF8(p.name),i+1);visiblePatches.push_back(i);}}if(chooseFirst&&!visiblePatches.empty()){current=visiblePatches.front();processor.setCurrentProgram(current);program=-1;notice=juce::String((int)visiblePatches.size())+" patches — loaded "+processor.getProgramName(current)+" on pad "+juce::String(processor.selectedPad.load()+1);noticeTicks=175;}if(std::find(visiblePatches.begin(),visiblePatches.end(),current)!=visiblePatches.end())patches.setSelectedId(current+1,juce::dontSendNotification);else patches.setTextWhenNothingSelected(visiblePatches.empty()?"No matching patches — choose All families":"Choose an instrument patch");previous.setEnabled(!visiblePatches.empty());next.setEnabled(!visiblePatches.empty());}
void WorldEditor::browse(int dir){if(visiblePatches.empty())return;auto found=std::find(visiblePatches.begin(),visiblePatches.end(),processor.getCurrentProgram());int i=found==visiblePatches.end()?(dir>0?-1:0):(int)(found-visiblePatches.begin());i=(i+dir+(int)visiblePatches.size())%(int)visiblePatches.size();processor.setCurrentProgram(visiblePatches[(size_t)i]);program=-1;}
void WorldEditor::timerCallback(){if(selected!=processor.selectedPad.load())select(processor.selectedPad.load());int p=processor.getCurrentProgram();if(program!=p){program=p;if(std::find(visiblePatches.begin(),visiblePatches.end(),p)!=visiblePatches.end())patches.setSelectedId(p+1,juce::dontSendNotification);else patches.setSelectedId(0,juce::dontSendNotification);}bool sample=processor.state.getRawParameterValue(WorldProcessor::id(selected,world::Source))->load()>.5f;auto&patch=world::patches[(size_t)p];editing.setText("EDITING PAD "+juce::String(selected+1)+"  /  "+(sample?processor.sampleName(selected):juce::String::fromUTF8(patch.instrument))+"  /  "+(sample?juce::String("Sample"):juce::String(world::regions[patch.region])),juce::dontSendNotification);int step=processor.playStep.load();uint32_t mask=processor.rhythms[(size_t)selected].load();for(int i=0;i<16;i++){steps[(size_t)i].setToggleState(bool(mask&(1u<<i)),juce::dontSendNotification);steps[(size_t)i].setColour(juce::TextButton::buttonOnColourId,i==step?juce::Colour(0xffffed00):accent);steps[(size_t)i].setColour(juce::TextButton::buttonColourId,i==step?juce::Colour(0xffffed00):juce::Colour(0xffa6afa0));pads[(size_t)i]->repaint();}autoplay.setButtonText(processor.state.getRawParameterValue("auto")->load()>.5f?"STOP / DISARM":"PLAY / ARM PADS");learnMidi.setButtonText(processor.learnPad.load()>=0?"HIT PAD / CANCEL":"LEARN PAD");int recState=processor.recordStatus.load();rec.setButtonText(recState==1?"REC "+juce::String(processor.recordingSeconds(),1)+"s":"REC");rec.setColour(juce::TextButton::buttonColourId,recState==1?juce::Colour(0xffe55641):juce::Colour(0xffa6afa0));useRec.setEnabled(recState==2);saveRecWav.setEnabled(recState==2);if(noticeTicks>0){status.setText(notice,juce::dontSendNotification);noticeTicks--;}else if(processor.learnPad.load()>=0)status.setText("MIDI LEARN: strike the hardware pad for selected VOG pad "+juce::String(processor.learnPad.load()+1),juce::dontSendNotification);else status.setText("MIDI note "+juce::String(processor.lastMidiNote.load())+" ch "+juce::String(processor.lastMidiChannel.load())+"  •  "+juce::String(processor.bpm.load(),1)+" BPM  •  REC "+juce::String(processor.recordingSeconds(),1)+" / 30 sec  •  Select a pad to edit its instrument, ADSR, rotary filter and FX  •  MIDI ch10 notes 36–51 trigger pads",juce::dontSendNotification);waveform.repaint();body.getProperties().set("peak",processor.peak.load());body.repaint();processor.cleanupSamples();}
