 auto panel=[&](float x,float y,float w,float h){auto r=juce::Rectangle<float>(x,y,w,h);g.setColour(juce::Colours::black.withAlpha(.55f));g.fillRoundedRectangle(r.translated(1,4),8);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff11171b),r.getTopLeft(),juce::Colour(0xff67655b),r.getBottomRight(),false));g.fillRoundedRectangle(r,8);auto face=r.reduced(3);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff394044),face.getTopLeft(),juce::Colour(0xff1c2327),face.getBottomRight(),false));g.fillRoundedRectangle(face,6);g.setColour(juce::Colour(0xffbd9a53).withAlpha(.65f));g.drawRoundedRectangle(r,8,1);for(float sx:{r.getX()+10,r.getRight()-10})for(float sy:{r.getY()+10,r.getBottom()-10}){auto screw=juce::Rectangle<float>(sx-3,sy-3,6,6);g.setGradientFill(juce::ColourGradient(juce::Colour(0xffc2b694),screw.getTopLeft(),juce::Colour(0xff272b2d),screw.getBottomRight(),false));g.fillEllipse(screw);g.setColour(juce::Colours::black);g.drawLine(sx-1.6f,sy-1.f,sx+1.6f,sy+1.f,1);}};
